"""CPU 해시·밀도 전수 분석의 재현 가능한 표와 문서. 장치 timing 없음."""
import csv,json,math,os
from pathlib import Path
P=Path(__file__).resolve().parent;G=P.parent;E=G.parents[1];R=G/'hash-functions-v1';D=G/'hash-density-v1';A=G/'hash-analysis-v1'
A.mkdir(exist_ok=False)
graphs=json.loads((P/'inputs.json').read_text());probe=[];load=[];density=[]
def ratio(a,b):return a/b if b else None
def fmt(v,d=3):return '—' if v is None else f'{v:.{d}f}'
def pct(v):return '—' if v is None else f'{100*v:.2f}%'
def csvout(name,rows):
 with (A/name).open('w') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
def quant(hist,q):
 n=sum(v for _,v in hist);k=int(q*(n-1));acc=0
 for d,v in hist:
  acc+=v
  if acc>k:return d/16384
 return None
for g in graphs:
 name=g['graph'];h=json.loads((R/name/'result.json').read_text());d=json.loads((D/name/'result.json').read_text());t=d['all_degree_gt_128'];assert h['degree_order_inversions']==0
 for fam in h['families']:
  pop=fam['population'];load.append(dict(graph=name,family=fam['family'],rows=pop['rows'],sampled_rows=pop['sampled_rows'],load_mean=ratio(pop['keys'],pop['rows']*16384),**{f'load_p{q}':quant(pop['degree_histogram'],q/100) for q in [0,50,90,99,100]},consecutive_pair_fraction=ratio(pop['consecutive_pairs'],pop['pairs']),same_degree_fraction_of_consecutive=ratio(pop['same_degree_consecutive_pairs'],pop['consecutive_pairs']),consecutive_runs=pop['consecutive_runs'],single_degree_run_fraction=ratio(pop['single_degree_runs'],pop['consecutive_runs'])))
  for slot in fam['hashes']:
   row=dict(graph=name,family=fam['family'],slot=slot['slot'],population_rows=pop['rows'],sampled_rows=pop['sampled_rows'])
   for key in ['inserted_success','actual_success','actual_unsuccess','uniform_unsuccess']:
    s=slot[key];row.update({key+'_queries':s['n'],key+'_mean':ratio(s['sum'],s['n']),key+'_max':s['max'] if s['n'] else None})
   probe.append(row)
 row=dict(graph=name,rows=t['rows'],actual_steptc_rows=d['actual_steptc_hash']['rows'],consecutive_pair_fraction=ratio(t['consecutive'],t['pairs']),consecutive_row_mean=ratio(t['sum_consecutive_ratio'],t['rows']),same_degree_fraction_of_consecutive=ratio(t['same_degree_consecutive'],t['consecutive']),consecutive_given_equal_degree=ratio(t['same_degree_consecutive'],t['degree_equal_pairs']),consecutive_given_unequal_degree=ratio(t['consecutive']-t['same_degree_consecutive'],t['pairs']-t['degree_equal_pairs']))
 for key in ['rho','span','consecutive']:
  for q,v in zip(['min','p50','p90','p99','max'],d[key+'_quantiles_min_p50_p90_p99_max']):row[key+'_'+q]=v
 for key in ['pearson_rho_consecutive','pearson_logrho_consecutive','pearson_logspan_consecutive']:row[key]=d[key]
 density.append(row)
csvout('probe-summary.csv',probe);csvout('load-and-degree-groups.csv',load);csvout('density-summary.csv',density)
lines=['# 해시 함수 CPU 비교와 연속 ID의 원인 분석', '', '2026-10-23. Mac에서 fixture를 검증하고 bear에서 CPU만 사용했다. TT/GPU timing을 측정하거나 추정한 결과가 아니다. `new_paper/`는 수정하지 않았다.', '', '## 핵심 판단', '', '**WebCC의 연속 ID는 높은 rank 구간의 밀집과 같은 degree 묶음 안의 국소성이 함께 나타나는 현상이다.** 고밀도 상위 구간은 연속 쌍이 어디에 집중되는지 설명하지만, 밀도만으로 WebCC와 Hollywood의 차이를 설명하지 못한다. 같은 degree 묶음이라는 사실도 단독으로 충분하지 않다(Friendster 대조). 아래는 관측적 분해이며 두 요인의 인과 기여율을 추정한 실험은 아니다.', '', '## 검증·범위', '', '- 입력 17개(기존 14 + roadNet-PA/TX/CA)의 SHA-256이 기준 메타데이터와 모두 일치했다. slot 비교 17/17, 밀도 전수 집계 17/17 완료, 실패 0. 별도 밀도 fixture 3/3 통과(독립 Python으로 행별 식·쌍 집계·분위수를 대조).', '- 밀도 분석은 **14개 그래프의 모든 `d+>128` 행**을 사용한다. 도로망 3개도 집계했으며 해당 행은 0이다. Facebook·Stanford·Google·Patents도 0이다. 해당 없음은 성능 0으로 해석하지 않는다.', '- StepTC D2의 실제 해시 행은 `d+>128`이면서 적어도 하나의 교집합 작업을 소유한 행이다. 양 끝 forward degree가 모두 양수인 edge에서 큰 degree의 행(동률이면 큰 ID)이 소유한다. TRUST B2는 `d+>=2`인 source 행을 사용하고, 마지막 target 제외·source 최대 ID까지 target prefix를 자르는 기존 후보 정의를 따른다.', '- probe 비교는 계열별 전체 적격 행 중 최대 512개를 균등 reservoir 표본으로 뽑았다(seed StepTC=20261022, TRUST=20261023). 행·부하율 분포와 degree 묶음·연속 쌍 통계는 **전수**다. `rows.jsonl`에 선정 행 ID와 후보 모집단 크기를 보존했다.', '- 표본 행의 삽입 key는 전부 success lookup으로 검사한다. 실제 후보는 행당 1,024개 이하면 전수, 초과하면 후보 위치에서 복원 균등 표본 1,024개다. 별도로 행당 전체 ID 공간의 uniform absent key 128개를 뽑았다. 네 slot 함수는 동일한 행·삽입 순서·query를 사용한다. 모든 lookup 결과를 정렬 행의 이진 탐색과 대조했다.', '- 아래 probe 평균은 **실제로 검사한 query의 평균**, 최대는 **표본 최대**다. 행별 query 상한 때문에 전체 장치 후보의 작업량 가중 평균을 추정하지 않는다. 특히 TRUST의 짧은 행이 많은 모집단에서 512행 표본은 드문 고비용 행을 놓칠 수 있다.', '', '## 정의', '', '`rank(u)`는 canonical CSR의 0-based ID다. 무방향 degree는 forward CSR의 outdegree+indegree로 복원했다. 17개 입력 모두 degree 순서 역전 0이다.', '', '- `ρ(u)=d+(u)/(n−rank(u))`: 요청한 분모를 그대로 사용한다. 실제 가능한 forward ID 수는 `n−rank(u)−1`이므로 이 값은 엄밀한 forward 영역 점유율과 한 칸 차이가 있다.', '- `s(u)=(max(N+(u))−min(N+(u))+1)/d+(u)`.', '- `c(u)=#{정렬한 인접 이웃 ID 쌍 중 차이가 1인 쌍}/(d+(u)−1)`.', '- “행 평균 c”는 각 행을 동일 가중, “쌍 비율 c”는 모든 인접 쌍을 합쳐 계산한다. 긴 행이 많은 그래프에서는 둘이 크게 다르다.', '- 같은 degree 비율은 **연속 쌍 중 양쪽 이웃의 무방향 degree가 같은 비율**이다. 완전한 연속 run이 단일 degree 묶음에 들어가는 비율도 별도 CSV에 있다.', '- `ρ`·`s`와 `c`는 같은 ID 집합에서 도출되는 관련 지표다. 특히 작은 범위 폭과 높은 연속성은 수학적으로 연결되므로, 상관계수를 독립적인 인과 증거로 쓰지 않는다.', '', '## 14개 그래프 전수 관계', '', '분위수는 정렬 배열의 `floor(q·(N−1))` 원소다. 전체 min/p50/p90/p99/max와 조건부 쌍 비율은 [density-summary.csv](optimization_20261022/gap/hash-analysis-v1/density-summary.csv)에 있다.', '', '| 그래프 | d+>128 행 | ρ 중앙값 | s 중앙값 | 행 평균 c | 쌍 비율 c | 연속 쌍 중 같은 degree | corr(ρ,c) | corr(log₁₀s,c) |', '|---|---:|---:|---:|---:|---:|---:|---:|---:|']
for row in density[:14]:
 lines.append(f"| {row['graph']} | {row['rows']:,} | {fmt(row['rho_p50'],6)} | {fmt(row['span_p50'],2)} | {pct(row['consecutive_row_mean'])} | {pct(row['consecutive_pair_fraction'])} | {pct(row['same_degree_fraction_of_consecutive'])} | {fmt(row['pearson_rho_consecutive'])} | {fmt(row['pearson_logspan_consecutive'])} |")
lines += ['', '![세 그래프의 밀도 및 범위 폭과 연속성](optimization_20261022/gap/hash-analysis-v1/density-relations.png)', '', '그림은 전수 행을 고정 구간으로 나눈 뒤 구간 내 행 평균을 표시한다. 전체 14개 그래프의 rho×span 교차 집계와 각 행 값은 `hash-density-v1/<graph>/result.json`, `rows.csv.gz`에 있다.', '', '## WebCC·Hollywood·Friendster: 두 가설의 구분', '', '| 그래프 | ρ>0.01인 행 비율 | 그 행들이 포함한 전체 연속 쌍 비율 | 0.1<ρ≤0.25에서 행 평균 c | 그 구간의 연속 쌍 중 같은 degree |', '|---|---:|---:|---:|---:|']
for name in ['webcc','hollywood','friendster']:
 d=json.loads((D/name/'result.json').read_text());t=d['all_degree_gt_128'];b=d['rho_bins'][4]
 lines.append(f"| {name} | {pct(ratio(sum(b['rows'] for b in d['rho_bins'][3:]),t['rows']))} | {pct(ratio(sum(b['consecutive'] for b in d['rho_bins'][3:]),t['consecutive']))} | {pct(ratio(b['sum_consecutive_ratio'],b['rows']))} | {pct(ratio(b['same_degree_consecutive'],b['consecutive']))} |")
lines += ['', '1. **상위 구간 밀집 가설은 집중 위치를 설명한다.** WebCC에서 ρ>0.01인 6.28%의 행에 연속 쌍 91.85%가 모인다. ρ와 c의 Pearson 상관은 0.554다. 다만 전체 행의 ρ 중앙값은 0.000190으로, 모든 해시 행이 좁은 최상위 구간에 밀집한다는 주장은 성립하지 않는다.', '2. **동일 밀도 구간에서도 WebCC의 ID 군집성이 훨씬 강하다.** 0.1<ρ≤0.25에서 WebCC의 평균 c는 98.37%, Hollywood는 22.86%다. 이 구간은 폭이 있는 관측적 층화이며 완전한 밀도·degree 매칭 실험은 아니다. 그래도 단순 “높은 rank 때문에 남은 공간이 작다”는 설명만으로는 부족하다.', '3. **WebCC에서 연속성을 이루는 직접적인 위치는 주로 같은 degree 묶음이다.** 연속 쌍의 95.25%가 같은 degree 안에 있다. 같은 degree인 인접 이웃 쌍 중 연속 비율은 90.13%, degree가 다른 쌍은 10.35%다. 높은 rank 밀집과 degree 묶음 내 국소성이 중첩되어 있다.', '4. **같은 degree 묶음이라는 사실만으로 연속성이 생기지는 않는다.** Friendster는 드물게 생긴 연속 쌍의 99.31%가 같은 degree지만, 전체 쌍 중 연속 쌍은 0.112%뿐이다. 같은 degree인 인접 이웃 쌍에서도 연속 비율은 1.26%다. 따라서 “같은 degree 비율이 높다”는 조건부 비율을 주원인의 단독 증거로 삼으면 안 된다.', '5. **범위 폭은 일부 먼 이웃에 민감하다.** WebCC에서 c≥0.9인 행은 110,963개지만 s≤1.1인 행은 0개다. 여러 조밀한 ID run 사이의 공백·먼 이웃 때문에 높은 연속성과 넓은 min–max 범위가 공존한다. “하나의 좁은 연속 구간”과 “여러 긴 연속 run”을 구별해야 한다.', '', '**논문에 쓸 수 있는 결론:** WebCC의 비용 문제는 degree 방향화 자체의 필연적 결과가 아니다. 상위 rank 쪽 고차수 행에 연속 쌍이 집중되고, 그 안에서 degree 동률을 보존한 ID 국소성이 긴 연속 run을 남긴다. 슬롯을 충분히 섞지 않는 선형 탐사에서는 이 배열이 긴 군집을 만들 수 있다. 어느 요인이 인과적으로 주된지를 확정하려면 degree 동률 내부 재배열 등 별도 대조가 필요하며, 이번 분석은 이를 실행하지 않았다.', '', '## 원래 WDC ID는 호스트명 순서인가?', '', '[공식 2012-08 다운로드](https://webdatacommons.org/hyperlinkgraph/2012-08/download.html)의 `sd-index.gz`를 bear에서 받아 **101,717,775행 전부**를 확인했다. bytewise 호스트명 순서 역전 0, ID 순서 위반 0, ID 간격 위반 0, 마지막 ID 101,717,774였다. 압축 스트림 CRC 검사도 완료했다. [공식 형식 설명](https://webdatacommons.org/hyperlinkgraph/index.html)은 이름·ID 두 열과 ID 정렬을 설명하며, 여기서 호스트명 정렬은 파일 자체에 대한 전수 검사의 결과다.', '', '- 인덱스 SHA-256: `ede75515ae3e0c13f496614063f4bdaa81164efd312bf8d3ce9b70d297716299`.', '- 실제 WebCC 전처리 코드 `hash-wdc-v1/original-prepare.cpp` SHA-256: `a12ea81aff942cc87794559743a0c96c63d21eb88784ce75c45bf1282d184ba8`.', '- 원래 arc를 무방향 단순 edge로 만들고 고립 정점을 제거한 뒤 `(무방향 degree, 원래 ID)`로 정렬하여 rank를 부여한다. 따라서 **같은 degree 안에서는 원래 호스트명 순서를 보존**한다. 방향화만으로 이 순서가 무작위화되지 않는다.', '- rank→원래 ID 매핑은 당시 산출물에 저장되지 않았다. 이번에는 호스트명과 개별 연속 run을 join하지 않았다. 따라서 호스트명 정렬 보존은 확인됐지만, 같은 사이트/도메인의 연결이 모든 run의 원인이라는 주장은 하지 않는다.', '', '## 슬롯 함수 4종과 probe 결과', '', '표 크기는 모두 16,384이고 삽입 순서는 정렬된 source 행이다. probe 길이는 **처음 접근과 마지막 equal/empty 슬롯을 포함**한다. 기존 TT counter의 nonmatching occupied-slot 추가 단계와 비교하려면 1을 빼야 한다.', '', '| 이름 | slot |', '|---|---|', '| identity | `y & 16383` |', '| xor-fold | `(y ^ (y >> 16)) & 16383` |', '| multiply-shift | `uint32(y * 0x9E3779B1) >> 18` |', '| avalanche | 현행 두 곱셈·세 xor 혼합 후 `&16383` |', '', '전체 17×2×4=136개 조합의 success/unsuccess 평균·최대·query 수는 [probe-summary.csv](optimization_20261022/gap/hash-analysis-v1/probe-summary.csv)에 있다. 해시 행이 없는 7개 그래프(StepTC: fb, stanford, google, patents, 도로망 3개)의 28조합은 해당 없음이며, 실제 probe가 있는 조합은 108개다.', '', '아래는 StepTC의 비교 대상 3개 그래프다. `실제 성공/실패`는 기존 알고리즘 후보에서 추출했고, `uniform 실패`는 전체 ID 공간의 부재 key다. 두 query 분포를 섞지 않았다.', '', '| 그래프 | slot | 실제 성공 평균 / 최대 | 실제 실패 평균 / 최대 | uniform 실패 평균 / 최대 |', '|---|---|---:|---:|---:|']
for row in probe:
 if row['family']!='steptc-D2' or row['graph'] not in ['webcc','hollywood','friendster']:continue
 vals=[fmt(row[k+'_mean'])+' / '+str(row[k+'_max']) for k in ['actual_success','actual_unsuccess','uniform_unsuccess']]
 lines.append('| '+' | '.join([row['graph'],row['slot'],*vals])+' |')
